begin;
alter table public.restaurant_ai_reports add column is_admin_run boolean not null default true,add column visible_to_restaurant boolean not null default false,add column shared_token text unique,add column share_enabled boolean not null default false,add column share_payload jsonb,add column prompt_version_id uuid,add column prompt_version integer,add column prompt_snapshot text;
create table public.ai_report_prompt_versions(id uuid primary key default gen_random_uuid(),version bigint generated always as identity unique,prompt text not null check(length(prompt)between 100 and 20000),created_at timestamptz not null default now(),created_by uuid references auth.users(id));
create table public.ai_report_features(id boolean primary key default true check(id),restaurant_ui_enabled boolean not null default false,active_prompt_id uuid references public.ai_report_prompt_versions(id));
alter table public.ai_report_prompt_versions enable row level security;alter table public.ai_report_features enable row level security;
revoke all on public.ai_report_prompt_versions,public.ai_report_features from public,anon,authenticated;
insert into public.ai_report_prompt_versions(prompt)values('Eres un consultor operativo de restaurantes. Tu trabajo es convertir la voz real del comensal en decisiones concretas para el dueño y gerente. Escribe en español claro, directo y útil, sin relleno ni lenguaje corporativo.

PRIORIDAD DEL ANÁLISIS
1. Dedica la mayor profundidad a TODAS las respuestas de texto abierto: qué molesta, qué valoran, qué piden, qué se repite, qué se contradice y qué situaciones concretas describen.
2. Agrupa expresiones equivalentes por significado (por ejemplo, demoras al cobrar y tardanza de la cuenta), sin confundir problemas distintos. Separa fortalezas que conviene repetir de fricciones que conviene corregir.
3. Usa calificaciones, opciones y tendencias para respaldar o matizar los comentarios. Una calificación alta no invalida una queja específica. No conviertas pocos comentarios en una verdad general.
4. Busca oportunidades reales en comida, preparación, temperatura, porciones, limpieza, ambiente, bienvenida, atención, coordinación y cobro, SOLO cuando los datos las mencionen. No rellenes categorías sin evidencia.
5. No te centres en cómo mejorar la encuesta o captar más respuestas. Eso es secundario y solo merece una nota si una limitación impide una decisión operativa.

QUÉ DEBE RECIBIR EL DUEÑO
- Un resumen que responda: qué debería cambiar, qué debería repetir y qué vigilar primero. Evita recitar las métricas que ya muestran las gráficas.
- Entre 3 y 6 hallazgos si hay evidencia: situación concreta, su impacto probable (marcado como hipótesis cuando corresponda), evidencia citada y prioridad. Incluye fortalezas aprovechables, no solo quejas.
- Temas claros de comentarios con sentimiento positivo, negativo o mixto. Las citas deben sostener el tema; no inventes conteos exhaustivos a partir de un subconjunto de referencias.
- Hasta 6 tareas operativas priorizadas, distintas y aplicables. Cada tarea debe indicar: cambiar / replicar / mejorar / investigar; un responsable PROPUESTO por función (gerencia, cocina o sala); un horizonte PROPUESTO; un paso concreto para ejecutar; por qué hacerlo; y una forma específica de comprobar el efecto. No presentes metas propuestas como resultados observados ni inventes objetivos numéricos sin base.
- Prefiere acciones específicas, como revisar un paso del cobro que los clientes mencionan, sobre generalidades como ''mejorar servicio'' o ''capacitar equipo''. No asumas cuál fue la causa: si hace falta, propone observar el proceso antes de cambiarlo.
- Si el texto abierto es escaso o no hay evidencia suficiente, dilo y entrega menos tareas. No inventes un problema para completar secciones.

COMPARACIÓN Y CONTINUIDAD
Usa el análisis previo solo como contexto. Revalida cada recomendación contra el snapshot actual. No afirmes que una acción se implementó, funcionó o falló si no contamos con ese registro. Conserva la evidencia que sigue vigente y diferencia señales nuevas de comentarios ya presentes.');
insert into public.ai_report_features(id,active_prompt_id)select true,id from public.ai_report_prompt_versions order by version desc limit 1;
alter table public.restaurant_ai_reports add foreign key(prompt_version_id)references public.ai_report_prompt_versions(id);
-- All reports created to date were generated by portal admins. They remain private.
create or replace function public.restaurant_ai_report_state(p_restaurant uuid,p_start date,p_end date,p_version uuid default null,p_employee uuid default null,p_rating integer default null)returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare latest public.restaurant_ai_reports; used_count integer; total_count integer;fresh_count integer;week_date date:=date_trunc('week',now() at time zone 'America/Monterrey')::date;
begin
 if auth.uid() is null or not public.is_portal_admin() then raise exception 'portal_admin_required' using errcode='42501';end if;
 if not exists(select 1 from public.restaurants r where r.id=p_restaurant) then raise exception 'invalid_restaurant';end if;
 if p_start is null or p_end is null or p_end<p_start or p_end-p_start>365 or p_end>(now() at time zone 'America/Monterrey')::date or (p_rating is not null and p_rating not between 1 and 5) then raise exception 'invalid_range';end if;
 if p_version is not null and not exists(select 1 from public.survey_versions v where v.id=p_version and v.restaurant_id=p_restaurant) then raise exception 'invalid_version';end if;
 if p_employee is not null and not exists(select 1 from public.employees e where e.id=p_employee and e.restaurant_id=p_restaurant) then raise exception 'invalid_employee';end if;
 update public.restaurant_ai_reports set status='failed' where restaurant_id=p_restaurant and status='running' and created_at<now()-interval '10 minutes';
 select * into latest from public.restaurant_ai_reports r where r.restaurant_id=p_restaurant and r.range_start=p_start and r.range_end=p_end and r.version_id is not distinct from p_version and r.employee_id is not distinct from p_employee and r.rating is not distinct from p_rating and r.status='completed' order by r.created_at desc limit 1;
 select count(*),count(*) filter(where not(s.id=any(coalesce(latest.source_ids,'{}'::uuid[])))) into total_count,fresh_count from public.survey_responses s where s.restaurant_id=p_restaurant and s.submitted_at>=(p_start::timestamp at time zone 'America/Monterrey') and s.submitted_at<least(((p_end+1)::timestamp at time zone 'America/Monterrey'),now()) and (p_version is null or s.survey_version_id=p_version) and(p_employee is null or s.employee_id=p_employee)and(p_rating is null or s.rating=p_rating);
 select (select count(*) from public.restaurant_ai_reports r where r.restaurant_id=p_restaurant and r.week_start=week_date and not r.is_admin_run and r.status in ('running','completed')) into used_count;
 return jsonb_build_object('report',case when latest.id is null then null else to_jsonb(latest)-'generated_by'-'source_ids'-'share_payload'-'prompt_snapshot' end,'matching_count',total_count,'new_count',fresh_count,'admin_run',true,'used',used_count,'limit',null,'remaining',null,'resets_at',(week_date+7)::timestamp at time zone 'America/Monterrey','running',exists(select 1 from public.restaurant_ai_reports r where r.restaurant_id=p_restaurant and r.status='running'));
end $$;
revoke all on function public.restaurant_ai_report_state(uuid,date,date,uuid,uuid,integer) from public;
grant execute on function public.restaurant_ai_report_state(uuid,date,date,uuid,uuid,integer) to authenticated;


create or replace function public.reserve_restaurant_ai_report(p_request uuid,p_restaurant uuid,p_start date,p_end date,p_version uuid default null,p_employee uuid default null,p_rating integer default null)returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare state jsonb; prior public.restaurant_ai_reports; snapshot jsonb;ids uuid[];
begin
 if auth.uid() is null or not public.is_portal_admin() then raise exception 'portal_admin_required' using errcode='42501';end if;
 if p_request is null then raise exception 'invalid_request';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_restaurant::text,0));
 state:=public.restaurant_ai_report_state(p_restaurant,p_start,p_end,p_version,p_employee,p_rating);
 select * into prior from public.restaurant_ai_reports where id=p_request;
 if found then
 if prior.restaurant_id is distinct from p_restaurant or prior.generated_by is distinct from auth.uid() or prior.range_start is distinct from p_start or prior.range_end is distinct from p_end or prior.version_id is distinct from p_version or prior.employee_id is distinct from p_employee or prior.rating is distinct from p_rating then raise exception 'request_scope_conflict';end if;
 if prior.status='completed' then return state||jsonb_build_object('outcome','already_saved');end if;
 if prior.status='running' then raise exception 'report_in_progress';end if;
 end if;
 if (state->>'matching_count')::integer=0 then return state||jsonb_build_object('outcome','no_new_responses');end if;
 if (state->>'running')::boolean then raise exception 'report_in_progress';end if;
 if (state->>'matching_count')::integer>5000 then raise exception 'report_too_large';end if;
 snapshot:=private.restaurant_report_snapshot(p_restaurant,p_start,p_end,p_version,p_employee,p_rating);
 if octet_length(snapshot::text)>1200000 then raise exception 'report_too_large';end if;
 select coalesce(array_agg(value::uuid),'{}'::uuid[])into ids from jsonb_array_elements_text(snapshot->'source_ids');
 snapshot:=snapshot-'source_ids';
 insert into public.restaurant_ai_reports(id,restaurant_id,generated_by,range_start,range_end,version_id,employee_id,rating,status,week_start,snapshot,source_ids)
 values(p_request,p_restaurant,auth.uid(),p_start,p_end,p_version,p_employee,p_rating,'running',date_trunc('week',now() at time zone 'America/Monterrey')::date,snapshot,ids)
 on conflict(id)do update set status='running',created_at=now(),week_start=excluded.week_start,snapshot=excluded.snapshot,source_ids=excluded.source_ids;
 update public.restaurant_ai_reports r set prompt_version_id=p.id,prompt_version=p.version,prompt_snapshot=p.prompt,is_admin_run=true from public.ai_report_prompt_versions p join public.ai_report_features f on f.active_prompt_id=p.id where r.id=p_request;
 return jsonb_build_object('prompt',(select jsonb_build_object('id',r.prompt_version_id,'version',r.prompt_version,'template',r.prompt_snapshot)from public.restaurant_ai_reports r where r.id=p_request),'outcome','reserved','snapshot',snapshot,'previous_output',state->'report'->'output','request_id',p_request);
end $$;
revoke all on function public.reserve_restaurant_ai_report(uuid,uuid,date,date,uuid,uuid,integer) from public;
grant execute on function public.reserve_restaurant_ai_report(uuid,uuid,date,date,uuid,uuid,integer) to authenticated;


drop function public.portal_ai_monitor(uuid,text,text,timestamptz,timestamptz,integer,uuid);
create function public.portal_ai_monitor(p_restaurant uuid default null,p_status text default 'all',p_environment text default 'all',p_from timestamptz default null,p_through timestamptz default null,p_page integer default 1,p_detail uuid default null,p_request uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb; week_date date:=date_trunc('week',now() at time zone 'America/Monterrey')::date;
begin
 if auth.uid() is null or not public.is_portal_admin()then raise exception 'portal_admin_required' using errcode='42501';end if;
 if p_status is null or p_status not in ('all','running','succeeded','failed','blocked','reused','abandoned')or p_environment is null or p_environment not in ('all','development','preview','production','unknown')or p_page is null or p_page not between 1 and 100000 or(p_from is not null and p_through is not null and p_through<=p_from)then raise exception 'invalid_filters';end if;
 with scoped as materialized(
 select o.*,r.name as restaurant_name,case when o.status='running'and o.updated_at<now()-interval '12 minutes'then 'abandoned'else o.status end as effective_status
 from public.ai_operations o left join public.restaurants r on r.id=o.restaurant_id
 where(p_request is null or o.request_id=p_request)and(p_restaurant is null or o.restaurant_id=p_restaurant)and(p_environment='all'or o.environment=p_environment)and(p_from is null or o.created_at>=p_from)and(p_through is null or o.created_at<p_through)
 ),filtered as materialized(select * from scoped where p_status='all'or effective_status=p_status),
 page_rows as(select * from filtered order by created_at desc,id limit 25 offset(p_page-1)*25),
 quotas as(
 select r.id,r.name,(select count(*)from public.restaurant_ai_reports a where a.restaurant_id=r.id and not a.is_admin_run and a.week_start=week_date and(a.status='completed'or(a.status='running'and a.created_at>=now()-interval '10 minutes')))as used
 from public.restaurants r where(p_restaurant is null or r.id=p_restaurant)
 )select jsonb_build_object(
 'summary',(select jsonb_build_object('attempts',count(*),'provider_calls',count(*)filter(where provider_started),'succeeded',count(*)filter(where effective_status='succeeded'),'failed',count(*)filter(where effective_status in ('failed','abandoned')),'blocked',count(*)filter(where effective_status='blocked'),'reused',count(*)filter(where effective_status='reused'),'running',count(*)filter(where effective_status='running'),'input_tokens',coalesce(sum(input_tokens),0),'output_tokens',coalesce(sum(output_tokens),0),'estimated_usd',coalesce(sum(estimated_usd),0),'unknown_usage',count(*)filter(where (provider_started and(input_tokens is null or output_tokens is null))or(metadata->>'billing_unknown')='true'),'logging_gaps',count(*)filter(where(metadata->>'audit_degraded')='true'),'average_ms',round(avg(duration_ms)filter(where duration_ms is not null)))from filtered),
 'total',(select count(*)from filtered),'rows',coalesce((select jsonb_agg(to_jsonb(p)order by p.created_at desc,p.id)from page_rows p),'[]'),
 'detail',(select to_jsonb(s)from scoped s where s.id=p_detail),'events',coalesce((select jsonb_agg(to_jsonb(e)order by e.id)from public.ai_operation_events e join scoped s on s.id=e.operation_id where s.id=p_detail),'[]'),
 'models',coalesce((select jsonb_agg(to_jsonb(m))from(select model,count(*)as attempts,coalesce(sum(estimated_usd),0)as estimated_usd from filtered group by model)m),'[]'),
 'quotas',coalesce((select jsonb_agg(to_jsonb(q)order by q.used desc,q.name)from quotas q where q.used>0),'[]'),
 'resets_at',(week_date+7)::timestamp at time zone 'America/Monterrey',
 'monthly_alert_usd',(select monthly_alert_usd from public.ai_monitor_settings where id),
 'month_estimated_usd',(select coalesce(sum(o.estimated_usd),0)from public.ai_operations o where o.created_at>=(date_trunc('month',now()at time zone 'America/Monterrey')at time zone 'America/Monterrey')),
 'daily',coalesce((select jsonb_agg(to_jsonb(d)order by d.day)from(select(created_at at time zone 'America/Monterrey')::date as day,count(*)as attempts,coalesce(sum(estimated_usd),0)as estimated_usd from filtered group by 1)d),'[]')
 )into result;return result;
end $$;
revoke all on function public.portal_ai_monitor(uuid,text,text,timestamptz,timestamptz,integer,uuid,uuid)from public;grant execute on function public.portal_ai_monitor(uuid,text,text,timestamptz,timestamptz,integer,uuid,uuid)to authenticated;


create function public.ai_report_prompt_settings()returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 if auth.uid()is null or not public.is_portal_admin()then raise exception 'portal_admin_required'using errcode='42501';end if;
 return jsonb_build_object('active',(select to_jsonb(p)from public.ai_report_prompt_versions p join public.ai_report_features f on f.active_prompt_id=p.id),'history',coalesce((select jsonb_agg(to_jsonb(h)order by h.version desc)from(select * from public.ai_report_prompt_versions order by version desc limit 20)h),'[]'));
end $$;
revoke all on function public.ai_report_prompt_settings()from public;grant execute on function public.ai_report_prompt_settings()to authenticated;
create function public.save_ai_report_prompt(p_prompt text,p_expected uuid)returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare current_id uuid;new_id uuid;
begin
 if auth.uid()is null or not public.is_portal_admin()then raise exception 'portal_admin_required'using errcode='42501';end if;
 select active_prompt_id into current_id from public.ai_report_features where id for update;
 if current_id is distinct from p_expected then raise exception 'prompt_version_conflict';end if;
 if length(trim(p_prompt))not between 100 and 20000 then raise exception 'invalid_prompt';end if;
 if exists(select 1 from public.ai_report_prompt_versions where id=current_id and prompt=p_prompt)then return public.ai_report_prompt_settings();end if;
 insert into public.ai_report_prompt_versions(prompt,created_by)values(p_prompt,auth.uid())returning id into new_id;
 update public.ai_report_features set active_prompt_id=new_id where id;
 return public.ai_report_prompt_settings();
end $$;
revoke all on function public.save_ai_report_prompt(text,uuid)from public;grant execute on function public.save_ai_report_prompt(text,uuid)to authenticated;
create function public.admin_ai_report_document(p_id uuid)returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 if auth.uid()is null or not public.is_portal_admin()then raise exception 'portal_admin_required'using errcode='42501';end if;
 select jsonb_build_object('report',to_jsonb(r)-'source_ids'-'generated_by'-'share_payload','privacy_values',coalesce((select jsonb_agg(jsonb_build_object('name',s.guest_name,'contact',s.guest_contact))from public.survey_responses s where s.id=any(r.source_ids)),'[]'))into result from public.restaurant_ai_reports r where r.id=p_id and r.status='completed';return result;
end $$;
revoke all on function public.admin_ai_report_document(uuid)from public;grant execute on function public.admin_ai_report_document(uuid)to authenticated;
create function public.manage_ai_report(p_id uuid,p_action text,p_value boolean default null,p_token text default null,p_payload jsonb default null)returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare result jsonb;
begin
 if auth.uid()is null or not public.is_portal_admin()then raise exception 'portal_admin_required'using errcode='42501';end if;
 perform 1 from public.restaurant_ai_reports where id=p_id and status='completed'for update;if not found then raise exception 'report_not_found';end if;
 if p_action='visibility'then
 if p_value is null then raise exception 'invalid_visibility';end if;
 update public.restaurant_ai_reports set visible_to_restaurant=p_value where id=p_id;
 elsif p_action='share'then
 if p_token is null or p_token !~ '^[a-f0-9]{64}$'or p_payload is null or jsonb_typeof(p_payload)<>'object'or octet_length(p_payload::text)>2000000 then raise exception 'invalid_share';end if;
 update public.restaurant_ai_reports set shared_token=coalesce(shared_token,p_token),share_enabled=true,share_payload=p_payload where id=p_id;
 elsif p_action='revoke'then
 update public.restaurant_ai_reports set shared_token=null,share_enabled=false,share_payload=null where id=p_id;
 else raise exception 'invalid_action';end if;
 select jsonb_build_object('visible_to_restaurant',visible_to_restaurant,'share_enabled',share_enabled,'shared_token',shared_token,'is_admin_run',is_admin_run)into result from public.restaurant_ai_reports where id=p_id;return result;
end $$;
revoke all on function public.manage_ai_report(uuid,text,boolean,text,jsonb)from public;grant execute on function public.manage_ai_report(uuid,text,boolean,text,jsonb)to authenticated;
create function public.shared_ai_report(p_token text)returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 if p_token is null or p_token !~ '^[a-f0-9]{64}$'then return null;end if;
 return(select share_payload from public.restaurant_ai_reports where shared_token=p_token and share_enabled and status='completed');
end $$;
revoke all on function public.shared_ai_report(text)from public;grant execute on function public.shared_ai_report(text)to anon,authenticated;
commit;
